from shiny import App, ui, render, reactive, Inputs, Outputs, Session

app_ui = ui.page_fluid(
    ui.layout_columns(
        # First column: controlling inputs
        ui.card(
            ui.input_slider("num", "Number (controls others)", min=1, max=10, value=5),
            ui.input_select("color", "Color (controls others)", choices=["Red", "Green", "Blue"], selected="Red"),
            title="Controllers"
        ),
        # Second column: controlled inputs
        ui.card(
            ui.input_slider("controlled_slider", "Controlled Slider", min=1, max=10, value=5),
            ui.input_select("controlled_select", "Controlled Select", choices=["Red", "Green", "Blue"], selected="Red"),
            title="Controlled Inputs"
        ),
        # Third column: more inputs and a tabset
        ui.card(
            ui.input_text("text_input", "Text Input", value="Hello"),
            ui.input_checkbox("checkbox_input", "Checkbox Input", value=False),
            ui.navset_tab(
                ui.nav("Tab 1", ui.output_text_verbatim("tab1_out")),
                ui.nav("Tab 2", ui.output_text_verbatim("tab2_out")),
                id="tabs"
            ),
            title="Other Inputs & Tabs"
        ),
        col_widths=[4, 4, 4]
    )
)

def server(input: Inputs, output: Outputs, session: Session):
    # Update controlled_slider based on num
    @reactive.effect
    def _():
        session.send_input_message("controlled_slider", {
            "value": input.num(),
            "min": 1,
            "max": input.num() * 2
        })

    # Update controlled_select based on color
    @reactive.effect
    def _():
        session.send_input_message("controlled_select", {
            "selected": input.color(),
            "choices": ["Red", "Green", "Blue", input.color() + "ish"]
        })

    # Update text_input and checkbox_input based on num and color
    @reactive.effect
    def _():
        session.send_input_message("text_input", {
            "value": f"Number: {input.num()}, Color: {input.color()}"
        })
        session.send_input_message("checkbox_input", {
            "value": input.num() % 2 == 0
        })

    @output
    @render.text
    def tab1_out():
        return f"Tab 1: Slider={input.controlled_slider()}, Select={input.controlled_select()}"

    @output
    @render.text
    def tab2_out():
        return f"Tab 2: Text={input.text_input()}, Checkbox={input.checkbox_input()}"

app = App(app_ui, server, debug=True)
